@startuml

class FurnitureLine {
  + Name : string
}

class Furniture {
  + Reference : string
  + SellingPrice : double
}

class ComponentType {
  + Code : int
  + ManufacturingPrice : double
  + Type : string
}

class Store {
  + Address : string
  + FaxNumber : string
}

class Order {
  + OrderNumber : int
  + Date : date
}

class OrderLine {
  + Quantity : int
}

FurnitureLine "1" *-- "*" Furniture : consistsOf
Furniture "*" -- "*" ComponentType : composedOf
Furniture "*" -- "1" FurnitureLine : belongsTo
Store "1" -- "*" Order : places
Order "1" *-- "*" OrderLine : contains
OrderLine "*" -- "1" Furniture : refersTo

@enduml

